# Instacart Grocery Integration
import requests

INSTACART_API_KEY = "8d19259c6b764d38b6cc0b72396131ae"
BASE_URL = "https://api.instacart.com/v1"

def create_grocery_list(recipe_ingredients):
    """Create grocery list from recipe"""
    response = requests.post(
        f"{BASE_URL}/shopping_list",
        headers={"Authorization": f"Bearer {INSTACART_API_KEY}"},
        json={"items": recipe_ingredients}
    )
    return response.json()

def find_products(ingredient, store_id=None):
    """Find specific products in stores"""
    params = {"query": ingredient}
    if store_id:
        params["store_id"] = store_id

    response = requests.get(
        f"{BASE_URL}/products/search",
        headers={"Authorization": f"Bearer {INSTACART_API_KEY}"},
        params=params
    )
    return response.json()

def get_delivery_slots(zip_code):
    """Get available delivery slots"""
    response = requests.get(
        f"{BASE_URL}/delivery_slots",
        headers={"Authorization": f"Bearer {INSTACART_API_KEY}"},
        params={"zip_code": zip_code}
    )
    return response.json()
